const csrfRes = $input.first().json;
const prev = $('Map Airtable to Mavely credentials').first().json;
const csrfToken = (csrfRes.body && csrfRes.body.csrfToken) || csrfRes.csrfToken;
if (!csrfToken) throw new Error('No csrfToken in CSRF response');
return [{ json: {
  mavelyEmail: prev.mavelyEmail,
  mavelyPassword: prev.mavelyPassword,
  creatorId: prev.creatorId,
  csrfToken
} }];

const loginItem = $input.first().json;
const prev = $('Merge CSRF with credentials').first().json;
const headers = loginItem.headers || loginItem.response?.headers || {};
const setCookie = headers['set-cookie'] || headers['Set-Cookie'];
let cookieHeader = '';
if (Array.isArray(setCookie)) {
  cookieHeader = setCookie.map(c => c.split(';')[0].trim()).join('; ');
} else if (typeof setCookie === 'string') {
  cookieHeader = setCookie.split(/[\r\n]+/).map(s => s.split(';')[0].trim()).filter(Boolean).join('; ');
}
if (!cookieHeader) {
  const keys = Object.keys(loginItem).join(', ');
  const status = loginItem.statusCode ?? loginItem.status ?? '?';
  throw new Error('No Set-Cookie in login response. statusCode=' + status + '. Keys: ' + keys + '. (Login may have failed or redirect was followed.)');
}
return [{ json: { cookieHeader, creatorId: prev.creatorId } }];

const sessionItem = $input.first().json;
const cookieNode = $('Extract session cookies').first().json;
const body = sessionItem.body ?? sessionItem;
if (body && body.error === 'RefreshAccessTokenError') {
  throw new Error('Mavely session error: ' + (body.error || 'expired'));
}
if (body && typeof body.user === 'object' && body.user !== null) {
  return [{ json: { cookieHeader: cookieNode.cookieHeader, creatorId: cookieNode.creatorId, sessionOk: true } }];
}
return [{ json: { cookieHeader: cookieNode.cookieHeader, creatorId: cookieNode.creatorId, sessionOk: false } }];

const row = $input.first().json;
const f = (key, ...alt) => row[key] ?? row[alt.find(k => row[k] !== undefined)];
const mavelyEmail = f('Email', 'mavelyEmail', 'email');
const mavelyPassword = f('Password', 'mavelyPassword', 'password');
const creatorId = f('Creator_ID', 'creatorId', 'Creator', 'creator_id') || 'unknown';
if (!mavelyEmail || !mavelyPassword) throw new Error('mavely_credentials table must have Email and Password (or mavelyEmail, mavelyPassword)');
return [{ json: { mavelyEmail, mavelyPassword, creatorId } }];

const item = $input.first().json;
const raw = item.raw_payload;
return [{ json: {
  'Creator ID': item.creator_id,
  'Source Platform': item.source_platform,
  'Period Start': item.period_start,
  'Period End': item.period_end,
  'Normalized Earnings': item.normalized_earnings ?? null,
  'Recorded At': item.recorded_at,
  'Raw Payload': typeof raw === 'object' ? JSON.stringify(raw) : (raw ?? ''),
  'Currency': item.currency ?? 'USD',
  'Raw Type': item.raw_type ?? 'commission'
} }];

const prev = $input.first().json;
const d = new Date();
const periodStart = new Date(d.getFullYear(), d.getMonth(), 1).toISOString().slice(0, 10);
const periodEnd = d.toISOString().slice(0, 10);
const query = "query ($v1:CreatorAnalyticsWhereInput!){creatorAnalyticsMetricsTotals(where:$v1){metrics{clicksCount,commission,sales,salesCount,conversion}" + "}}";
const v1 = { cstDateStr_gte: periodStart, cstDateStr_lte: periodEnd };
v1.brand = { slug_not: "amazon-deep-linking" };
const variables = { v1 };
return [{ json: { cookieHeader: prev.cookieHeader, creatorId: prev.creatorId, periodStart, periodEnd, graphqlBody: JSON.stringify({ query, variables }) } }];

const res = $input.first().json;
const prep = $('Prepare Mavely GraphQL').first().json;
const body = res.body ?? res;
const data = body.data ?? body;
const totals = data.creatorAnalyticsMetricsTotals;
const metrics = totals && totals.metrics ? totals.metrics : {};
const commission = typeof metrics.commission === 'number' ? metrics.commission : (parseFloat(metrics.commission) || null);
const out = {
  creator_id: prep.creatorId || 'unknown',
  source_platform: 'mavely',
  period_start: prep.periodStart,
  period_end: prep.periodEnd,
  normalized_earnings: commission,
  recorded_at: new Date().toISOString(),
  currency: 'USD',
  raw_payload: metrics,
  raw_type: 'commission'
};
return [{ json: out }];
